{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "조회 병목의 원인에 비추어 캐시보다 인덱스와 조인 수정을 선택한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 운영 화면의 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "조회가 느린 원인을 찾아 그 원인에 맞는 개선 방법을 선택해야 했다.",
          "action": "실행 계획에서 발견한 병목을 인덱스 추가와 조인 정리에 연결해 설명한다.",
          "result": "조회 시간이 0.4초로 줄어든 측정 결과로 선택의 효과를 뒷받침한다."
        },
        "expectedEvidence": [
          "캐시 대신 쿼리 개선을 선택한 이유를 병목 원인과 연결한다.",
          "실행 계획에서 확인한 내용을 인덱스와 조인 수정의 근거로 든다.",
          "개선 전후 조회 시간으로 선택한 방법의 효과를 설명한다."
        ]
      },
      "question": "포켓마켓 인턴 때 인덱스 추가와 조인 정리로 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 캐시 대신 쿼리 개선을 선택하신 이유는 무엇이었나요?",
      "answerTip": "당시 선택한 이유를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 발견한 병목을 근거로 캐시보다 쿼리 개선을 선택한 이유를 구체적으로 설명한다.",
            "인덱스와 조인 수정이 병목을 줄인 관계를 설명하고 전후 조회 시간으로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "쿼리 개선을 선택한 이유는 답하지만 실행 계획이나 수정 내용과의 연결이 일반적이다.",
            "조회 시간이 줄었다고 설명하나 선택한 방법의 효과를 뒷받침하는 근거가 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "쿼리 개선을 선택한 이유 없이 작업 내용이나 결과 수치만 반복한다.",
            "신고 목록 조회의 병목과 무관한 기술 장점만 나열한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 확인한 중복 실행 원인에 맞춰 일시적 중단보다 잠금 방식을 선택한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔다.",
          "task": "중복 발송 원인을 좁히고 같은 원인으로 장애가 반복되지 않는 조치를 선택해야 했다.",
          "action": "두 서버의 동시 실행 로그를 근거로 잠금과 일시적 중단의 차이를 설명한다.",
          "result": "잠금 적용 후 중복 발송 여부를 확인한 결과로 조치의 효과를 뒷받침한다."
        },
        "expectedEvidence": [
          "서버 한 대의 실행 중단 대신 잠금을 둔 이유를 재발 가능성과 연결한다.",
          "두 서버의 동시 실행 로그를 잠금 선택의 근거로 설명한다.",
          "잠금 적용 후 중복 발송 여부로 조치의 효과를 확인한다."
        ]
      },
      "question": "포켓마켓 인턴 때 두 서버의 스케줄러 중복 실행을 잠금으로 고치셨던데요. 서버 한 대의 스케줄러를 끄는 대신 왜 잠금을 두셨나요?",
      "answerTip": "그때 선택한 방법에 초점을 맞춰 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "동시 실행 로그를 근거로 일시적 실행 중단과 잠금의 차이를 재발 가능성에 연결해 설명한다.",
            "잠금 적용 뒤 중복 발송 여부를 확인한 결과로 조치의 효과를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "잠금을 선택한 이유는 답하지만 일시적 중단과 재발 방지의 차이는 일반적으로 설명한다.",
            "동시 실행 로그나 조치 후 결과를 구체적으로 연결하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금을 선택한 이유 없이 잠금을 적용했다는 사실만 반복한다.",
            "잠금 선택을 중복 실행 원인이나 같은 장애의 재발 가능성과 연결하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 나온 요구를 구현 범위로 정리할 때 적용한 판단 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스 과제에서 세탁소 다섯 곳을 인터뷰하고 개발 담당 팀원과 범위를 조정했다.",
          "task": "인터뷰에서 나온 요구를 과제에서 구현할 범위로 구체화해야 했다.",
          "action": "서비스 목적과 구현 제약을 근거로 요구사항의 포함 여부를 구분했다.",
          "result": "개발 담당 팀원과 구현할 요구사항의 경계를 합의했다."
        },
        "expectedEvidence": [
          "인터뷰에서 나온 요구를 구현 범위에 넣은 기준을 설명한다.",
          "실제 요구사항의 포함 여부를 해당 기준과 연결한다.",
          "개발 담당 팀원과 합의한 범위를 구체적으로 설명한다."
        ]
      },
      "question": "세탁소 다섯 곳을 인터뷰한 예약 서비스 과제에서 개발 담당 팀원과 범위를 조정하셨던데요. 인터뷰로 나온 요구를 구현 범위에 넣은 기준은 무엇이었나요?",
      "answerTip": "당시 실제로 내린 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위에 넣은 기준을 실제 요구사항의 포함 여부와 연결해 설명한다.",
            "그 기준으로 개발 담당 팀원과 합의한 범위를 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위를 정한 기준은 설명하지만 실제 요구사항이나 합의한 범위와의 연결은 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항을 나열하거나 문서 작성 사실만 말하고 구현 범위를 정한 기준은 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 사용자가 보게 될 화면 상태와 후속 행동으로 구체화한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "예외 발생 시 보여 줄 화면을 구현 가능한 수준으로 설계해야 했다.",
          "action": "예외의 발생 조건과 사용자가 이어서 할 행동에 따라 화면을 정했다.",
          "result": "예외 발생 시의 화면 상태와 안내가 화면설계서에서 명확해졌다."
        },
        "expectedEvidence": [
          "예외 상황에서 보여 줄 화면을 정한 근거를 설명한다.",
          "실제 예외의 발생 조건을 화면 상태와 연결한다.",
          "해당 화면의 안내나 후속 행동을 구체적으로 설명한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요. 예외 상황에서 사용자에게 보여 줄 화면은 무엇을 기준으로 정하셨나요?",
      "answerTip": "직접 작성했던 내용을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 예외의 발생 조건과 연결해 사용자에게 보여 줄 화면을 정한 근거를 설명한다.",
            "해당 화면의 상태와 안내 또는 후속 행동을 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면을 정한 기준은 답하지만 예외 조건이나 실제 화면에 대한 설명은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 수나 사용한 도구만 설명하고 예외 상황의 화면을 정한 근거는 답하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 용량의 처방을 의도된 증량으로 받아들이지 않고 투약 전 재확인한 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 환자에게 평소 두 배 용량의 진통제가 처방되었다.",
          "task": "처방된 용량을 그대로 투약해도 되는지 확인해야 했다.",
          "action": "용량의 적절성을 확신할 수 없는 근거에 따라 투약을 멈추고 담당의에게 확인했다.",
          "result": "담당의 확인으로 입력 오류를 발견해 잘못된 용량의 투약을 막았다."
        },
        "expectedEvidence": [
          "의도된 증량으로 단정할 수 없었던 구체적인 근거를 설명한다.",
          "불확실한 처방의 투약을 멈추고 담당의에게 확인한 행동을 설명한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배 용량의 진통제 투약을 멈추셨던데요. 의도된 증량일 수도 있는 처방을 바로 투약하지 않은 이유는 무엇이었나요?",
      "answerTip": "당시 실제로 한 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "당시 확인한 정보를 바탕으로 의도된 증량인지 확신할 수 없었던 이유를 구체적으로 설명한다.",
            "불확실한 상태에서 투약을 보류하고 담당의 확인을 거친 행동이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "두 배 용량이라 재확인이 필요했다고 답하지만, 당시 판단 근거는 일반적인 안전 원칙에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "바로 투약하지 않은 이유를 설명하지 못하거나, 확인되지 않은 처방도 그대로 수행한다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "낙상 예방 인수인계에서 진통제 투여 시각을 환자 상태 관찰에 필요한 정보로 연결한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동 사고 보고서에서 수술 후 첫 보행 환자의 낙상이 교대 시간대에 집중된 점을 확인했다.",
          "task": "교대 후에도 환자 상태 관찰이 이어지도록 인수인계에 필요한 정보를 정해야 했다.",
          "action": "진통제 투여 시각을 다음 근무자가 알아야 할 정보로 판단해 체크리스트에 추가하도록 제안했다.",
          "result": "다음 근무자가 투여 시각을 참고해 환자 상태를 이어서 관찰할 수 있도록 한다."
        },
        "expectedEvidence": [
          "진통제 투여 시각을 다음 근무자가 알아야 하는 이유를 환자 상태와 연결해 설명한다.",
          "기록된 투여 시각이 교대 후 환자 상태 관찰에 주는 의미를 구체적으로 설명한다."
        ]
      },
      "question": "푸른결종합병원에서 낙상 예방 인수인계에 진통제 투여 시각을 추가하셨던데요. 투여 시각을 다음 근무자가 꼭 알아야 한다고 본 이유는 무엇이었나요?",
      "answerTip": "그때의 상황을 떠올리며 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투여 시각을 인계해야 하는 이유를 수술 후 첫 보행 환자의 상태 변화와 구체적으로 연결한다.",
            "다음 근무자가 투여 시각을 바탕으로 어떤 상태를 주의 깊게 관찰할 수 있는지 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투여 시각을 인계해야 하는 이유는 답하지만, 환자 상태 관찰과의 연결은 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투여 시각을 전달해야 하는 이유를 설명하지 못하거나, 낙상 건수 감소만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "과제에서 주어진 하중과 부품 결합 조건을 실제 축 지름을 정하는 근거로 연결할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업에서 주어진 하중으로 감속기 축 지름과 베어링을 선정한 상황이다.",
          "task": "축 지름을 결정하는 핵심 조건을 파악하고 선택한 치수의 근거를 설명해야 했다.",
          "action": "하중 계산이나 베어링 결합 조건 중 실제 판단에 사용한 근거를 축 지름과 연결한다.",
          "result": "선정한 축 지름이 핵심 설계 조건을 만족하는 이유가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "최종 축 지름을 결정한 핵심 조건을 구체적으로 설명한다.",
          "하중 계산 또는 베어링 결합 조건을 선택한 지름의 근거로 연결한다."
